#include <ggZZcapture.hpp>

#include <complex>
#include <string>

#include <constants_mod.hpp>
#include <first_mod.hpp>
#include <ggZZ_mod.hpp>
#include <ZZclabels_mod.hpp>
#include <ZZdlabels_mod.hpp>

using namespace constants_mod;
using namespace first_mod;
using namespace ggZZ_mod;
using namespace ZZclabels_mod;
using namespace ZZdlabels_mod;

//--- This is called from within the coefficient-computing routines;
//--- captures m^0, m^2 and m^4 parts of the coefficient and stores
//--- in a common block
void ggZZcapture(const std::string& label, int h34, int h56, int j1, int j2, int j3, int j4, int j5, int j6,
    std::complex<double>& amp0, std::complex<double>& amp2, std::complex<double>& amp4) {
  const int imt0 = 1, imt2 = 2, imt4 = 3;
  const int ipp = 1, imp = 2;
  int htag, ltag, itag;

  if (first) {
    for (size_t l = 1; l <= res.nl; l++) {
      for (size_t k = 1; k <= res.nk; k++) {
        for (size_t j = 1; j <= res.nj; j++) {
          for (size_t i = 1; i <= res.ni; i++) {
            res(i, j, k, l) = czip;
          }
        }
      }
    }
    first = false;
  }

  htag = -1;

  // Fortran's trim(label) strips only trailing blanks; the _fi.F90 shim
  // already crosses the C boundary with trim(label), so `label` here stands
  // in for trim(label) directly.
  const std::string& trimmed = label;

  //--- Canonical permutation:  1 2 3 4 5 6
  if ((j1 == 1) && (j2 == 2) && (j3 == 3) && (j4 == 4) && (j5 == 5) && (j6 == 6)) {
    if ((trimmed == "1x2") && (h34 == 1) && (h56 == 1)) {
      htag = imp;
      ltag = 3;
      itag = c1_2;
    }
    if ((trimmed == "1x2pp") && (h34 == 1) && (h56 == 1)) {
      htag = ipp;
      ltag = 3;
      itag = c1_2;
    }
    if ((trimmed == "1x34") && (h34 == 1) && (h56 == 1)) {
      htag = imp;
      ltag = 3;
      itag = c1_34;
    }
    if ((trimmed == "1x34pp") && (h34 == 1) && (h56 == 1)) {
      htag = ipp;
      ltag = 3;
      itag = c1_34;
    }
    if ((trimmed == "12x34") && (h34 == 1) && (h56 == 1)) {
      htag = imp;
      ltag = 3;
      itag = c12_34;
    }
    if ((trimmed == "12x34pp") && (h34 == 1) && (h56 == 1)) {
      htag = ipp;
      ltag = 3;
      itag = c12_34;
    }
    if ((trimmed == "1x34x2mp") && (h34 == 1) && (h56 == 1)) {
      htag = imp;
      ltag = 4;
      itag = d1_34_2;
    }
    if ((trimmed == "1x34x2pp") && (h34 == 1) && (h56 == 1)) {
      htag = ipp;
      ltag = 4;
      itag = d1_34_2;
    }
    if ((trimmed == "2x1x34pp") && (h34 == 1) && (h56 == 1)) {
      htag = ipp;
      ltag = 4;
      itag = d2_1_34;
    }
    if ((trimmed == "2x1x34") && (h34 == 1) && (h56 == 1)) {
      htag = imp;
      ltag = 4;
      itag = d2_1_34;
    }
    if ((trimmed == "d62x1x34") && (h34 == 1) && (h56 == 1)) {
      htag = imp;
      ltag = 4;
      itag = d6_2_1_34;
    }
    if ((label.size() >= 6) && (label.compare(0, 5, "bubmp") == 0) && (h34 == 1) && (h56 == 1)) {
      htag = imp;
      ltag = 2;
      itag = label[5] - '0';
    }
    if ((label.size() >= 6) && (label.compare(0, 5, "bubpp") == 0) && (h34 == 1) && (h56 == 1)) {
      htag = ipp;
      ltag = 2;
      itag = label[5] - '0';
    }
  }

  //--- Permute 1 and 2:  2 1 3 4 5 6
  if ((j1 == 2) && (j2 == 1) && (j3 == 3) && (j4 == 4) && (j5 == 5) && (j6 == 6)) {
    if ((trimmed == "1x34") && (h34 == 1) && (h56 == 1)) {
      htag = imp;
      ltag = 3;
      itag = c2_34;
      if (amp0 != czip) amp0 = std::conj(amp0);
      if (amp2 != czip) amp2 = std::conj(amp2);
      if (amp4 != czip) amp4 = std::conj(amp4);
    }
    if ((trimmed == "1x34pp") && (h34 == 1) && (h56 == 1)) {
      htag = ipp;
      ltag = 3;
      itag = c2_34;
      if (amp0 != czip) amp0 = std::conj(amp0);
      if (amp2 != czip) amp2 = std::conj(amp2);
      if (amp4 != czip) amp4 = std::conj(amp4);
    }
    if ((trimmed == "2x1x34") && (h34 == 1) && (h56 == 1)) {
      htag = imp;
      ltag = 4;
      itag = d1_2_34;
      if (amp0 != czip) amp0 = std::conj(amp0);
      if (amp2 != czip) amp2 = std::conj(amp2);
      if (amp4 != czip) amp4 = std::conj(amp4);
    }
    if ((trimmed == "d62x1x34") && (h34 == 1) && (h56 == 1)) {
      htag = imp;
      ltag = 4;
      itag = d6_1_2_34;
      if (amp0 != czip) amp0 = std::conj(amp0);
      if (amp2 != czip) amp2 = std::conj(amp2);
      if (amp4 != czip) amp4 = std::conj(amp4);
    }
  }

  //--- Permute 3,4 and 5,6:  1 2 5 6 3 4
  if ((j1 == 1) && (j2 == 2) && (j3 == 5) && (j4 == 6) && (j5 == 3) && (j6 == 4)) {
    if ((trimmed == "1x34") && (h34 == 1) && (h56 == 1)) {
      htag = imp;
      ltag = 3;
      itag = c1_56;
    }
    if ((trimmed == "1x34pp") && (h34 == 1) && (h56 == 1)) {
      htag = ipp;
      ltag = 3;
      itag = c1_56;
    }
    if ((trimmed == "2x1x34pp") && (h34 == 1) && (h56 == 1)) {
      htag = ipp;
      ltag = 4;
      itag = d1_2_34;
    }
  }

  //--- Permute 1,3,4 and 2,5,6:  2 1 3 4 5 6
  if ((j1 == 2) && (j2 == 1) && (j3 == 5) && (j4 == 6) && (j5 == 3) && (j6 == 4)) {
    if ((trimmed == "1x34") && (h34 == 1) && (h56 == 1)) {
      htag = imp;
      ltag = 3;
      itag = c2_56;
      if (amp0 != czip) amp0 = std::conj(amp0);
      if (amp2 != czip) amp2 = std::conj(amp2);
      if (amp4 != czip) amp4 = std::conj(amp4);
    }
    if ((trimmed == "1x34pp") && (h34 == 1) && (h56 == 1)) {
      htag = ipp;
      ltag = 3;
      itag = c2_56;
      if (amp0 != czip) amp0 = std::conj(amp0);
      if (amp2 != czip) amp2 = std::conj(amp2);
      if (amp4 != czip) amp4 = std::conj(amp4);
    }
  }

  if (htag < 0) {
    return;
  }

  //--- assign results
  // @coverage-probe
  res(htag, ltag, itag, imt0) = amp0;
  res(htag, ltag, itag, imt2) = amp2;
  res(htag, ltag, itag, imt4) = amp4;

  if (std::abs(res(htag, ltag, itag, imt0)) < 1e-8) res(htag, ltag, itag, imt0) = czip;
  if (std::abs(res(htag, ltag, itag, imt2)) < 1e-8) res(htag, ltag, itag, imt2) = czip;
  if (std::abs(res(htag, ltag, itag, imt4)) < 1e-8) res(htag, ltag, itag, imt4) = czip;

  return;
}

extern "C" {
  void ggZZcapture_wrapper(const char* label, int h34, int h56, int j1, int j2, int j3, int j4, int j5, int j6,
      std::complex<double>& amp0, std::complex<double>& amp2, std::complex<double>& amp4) {
    std::string label_str(label);
    ggZZcapture(label_str, h34, h56, j1, j2, j3, j4, j5, j6, amp0, amp2, amp4);
  }
}
