// ----hep-ph/9708239, Eqs(8.4,8.8,8.14,9.2,9.7,10.1) Multiplied by (-i)

std::complex<double> a6treeg(int st, int j1, int j2, int j3, int j4, int j5, int j6, FArray2D<std::complex<double>>& za, FArray2D<std::complex<double>>& zb) {
  using namespace mxpart_mod;
  using namespace sprods_com_mod;
  using namespace heldefs_mod;

  std::complex<double> a6treeg_value;

  if (st == hqpgmgpqbm) {
    a6treeg_value =
      ((za(j2,j4)*za(j4,j5)*zb(j1,j3)*zb(j1,j6))/
      (s(j2,j3)*s(j5,j6)*za(j3,j4)*zb(j1,j2))-
      (za(j4,j5)*std::pow(zb(j1,j3),2)*(-(za(j1,j2)*zb(j1,j6))+za(j2,j3)*zb(j3,j6)))/
      (s(j2,j3)*s(j5,j6)*zb(j1,j2)*t(j1,j2,j3))+
      (std::pow(za(j2,j4),2)*zb(j1,j6)*(-(za(j2,j5)*zb(j2,j3))+za(j4,j5)*zb(j3,j4)))/
      (s(j2,j3)*s(j5,j6)*za(j3,j4)*t(j2,j3,j4)));
  } else if (st == hqpgpgmqbm) {
    a6treeg_value =
      (-(((za(j3,j5)*zb(j2,j3)+za(j4,j5)*zb(j2,j4))*
      (-(za(j1,j3)*zb(j1,j6))-za(j2,j3)*zb(j2,j6)))/
      (s(j2,j3)*s(j5,j6)*za(j1,j2)*zb(j3,j4)))-
      (za(j1,j3)*za(j4,j5)*zb(j1,j2)*
      (-(za(j1,j3)*zb(j1,j6))-za(j2,j3)*zb(j2,j6)))/
      (s(j2,j3)*s(j5,j6)*za(j1,j2)*t(j1,j2,j3))+
      (za(j3,j4)*zb(j1,j6)*zb(j2,j4)*
      (za(j3,j5)*zb(j2,j3)+za(j4,j5)*zb(j2,j4)))/
      (s(j2,j3)*s(j5,j6)*zb(j3,j4)*t(j2,j3,j4)));
